import json, threading, unittest, urllib.request, urllib.error
import server

class RuntimeTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.http = server.ThreadingHTTPServer(('127.0.0.1', 0), server.Handler)
        cls.url = 'http://127.0.0.1:' + str(cls.http.server_port)
        threading.Thread(target=cls.http.serve_forever, daemon=True).start()
    @classmethod
    def tearDownClass(cls):
        cls.http.shutdown(); cls.http.server_close()
    def post(self, action, value):
        req = urllib.request.Request(self.url+'/api/'+action, data=json.dumps(value).encode(), headers={'Content-Type':'application/json'})
        try:
            with urllib.request.urlopen(req) as r: return r.status, json.load(r)
        except urllib.error.HTTPError as e: return e.code, json.load(e)
    def test_room_lifecycle(self):
        _, s = self.post('create', {'client':'a'})
        code=s['code']; base={'code':code,'client':'b'}
        self.assertEqual(self.post('state',base)[1]['members'],2)
        s=self.post('control',dict(base,position=33,playing=True))[1]
        self.assertTrue(s['playing']); self.assertGreaterEqual(s['position'],33)
        self.assertEqual(self.post('control',dict(base,position=45,playing=False))[1]['position'],45)
        revision=self.post('state',base)[1]['revision']
        for value in (None, [], {'client':'bad','code':code,'position':True,'playing':True}, dict(base,position=float('nan'),playing=True), dict(base,position=91,playing=True)):
            self.assertEqual(self.post('control',value)[0],400)
        self.assertEqual(self.post('state',base)[1]['revision'],revision)
        self.assertEqual(self.post('leave',base)[1]['members'],1)
        server.rooms[code]['members']['a']-=9
        self.assertEqual(self.post('state',base)[1]['members'],1)
        # Restart semantics: in-memory rooms are lost, not silently recreated.
        with server.lock: server.rooms.clear()
        self.assertEqual(self.post('state',base)[0],404)
        self.assertEqual(self.post('create',{'client':'a'})[0],200)
    def test_video_ranges(self):
        req=urllib.request.Request(self.url+'/video.mp4',headers={'Range':'bytes=10-29'})
        with urllib.request.urlopen(req) as r:
            self.assertEqual(r.status,206); self.assertEqual(len(r.read()),20)
        req=urllib.request.Request(self.url+'/video.mp4',headers={'Range':'bytes=999999999-'})
        with self.assertRaises(urllib.error.HTTPError) as e: urllib.request.urlopen(req)
        self.assertEqual(e.exception.code,416)

if __name__=='__main__': unittest.main(verbosity=2)

